def grid_mappings(m):
    g={}
    # block splits
    for sn,edges in splits.items():
        cnt=np.zeros((3,3),int)
        for i,(r0,r1) in enumerate(edges):
            for j,(c0,c1) in enumerate(edges):
                cnt[i,j]=m[r0:r1,c0:c1].sum()
        g[f'blk_{sn}']=cnt
    # stride2 windows
    cnt=np.zeros((3,3),int)
    for i in range(3):
        for j in range(3):
            cnt[i,j]=m[2*i:2*i+3,2*j:2*j+3].sum()
    g['win_stride2']=cnt
    # mod3 histogram
    h=np.zeros((3,3),int)
    for r,c in np.argwhere(m): h[r%3,c%3]+=1
    g['mod3']=h
    # scale3
    h=np.zeros((3,3),int)
    for r,c in np.argwhere(m): h[r*3//7,c*3//7]+=1
    g['scale3']=h
    # clipped //2
    h=np.zeros((3,3),int)
    for r,c in np.argwhere(m): h[min(r//2,2),min(c//2,2)]+=1
    g['half']=h
    return g
